<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
type Node={id:string;label:string;url:string;tags:string[];category:string};
const props=defineProps<{base:string}>();const nodes=ref<Node[]>([]);const edges=ref<string[][]>([]);const selected=ref('');const failed=ref(false);
onMounted(async()=>{try{const response=await fetch(`${props.base}data/graph.json`);if(!response.ok)throw new Error();const data=await response.json();nodes.value=data.nodes.slice(0,100);edges.value=data.edges;}catch{failed.value=true;}});
const groups=computed(()=>[...new Set(nodes.value.map(node=>node.category))]);
const visible=computed(()=>nodes.value.filter(node=>!selected.value||node.category===selected.value));
function point(index:number){const angle=(index/nodes.value.length)*Math.PI*2;const radius=150+((index*37)%80);return{x:250+Math.cos(angle)*radius,y:230+Math.sin(angle)*radius}}
</script>
<template><section class="graph-view"><label>主題 <select v-model="selected"><option value="">所有主題</option><option v-for="group in groups" :key="group" :value="group">{{ group }}</option></select></label><p v-if="failed" class="empty-state">知識關聯資料載入失敗。<button type="button" @click="location.reload()">重試</button></p><div v-else class="graph-wrap"><svg class="graph-canvas" viewBox="0 0 500 460" role="img" aria-label="公開文章之間的標籤關聯圖"><g v-for="edge in edges" :key="edge.join('-')"><line v-if="visible.some(n=>n.id===edge[0])&&visible.some(n=>n.id===edge[1])" :x1="point(nodes.findIndex(n=>n.id===edge[0])).x" :y1="point(nodes.findIndex(n=>n.id===edge[0])).y" :x2="point(nodes.findIndex(n=>n.id===edge[1])).x" :y2="point(nodes.findIndex(n=>n.id===edge[1])).y" stroke="var(--border)" /></g><a v-for="node in visible" :key="node.id" :href="`${base}articles/${node.url.replace(/^\/articles\//,'')}`"><circle :cx="point(nodes.indexOf(node)).x" :cy="point(nodes.indexOf(node)).y" r="9" fill="var(--primary)" stroke="var(--text)"/><text :x="point(nodes.indexOf(node)).x+12" :y="point(nodes.indexOf(node)).y+4" fill="var(--text)" font-size="11">{{ node.label.slice(0,18) }}</text></a></svg><div class="graph-list"><h2>文章清單</h2><ul><li v-for="node in visible" :key="node.id"><a :href="`${base}articles/${node.url.replace(/^\/articles\//,'')}`">{{ node.label }}</a></li></ul></div></div></section></template>
